1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="UTF-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1.0">
6	<title>Sovereign — Final</title>
7	<style>
8	  @import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@700;900&family=Bricolage+Grotesque:opsz,wght@12..96,400;12..96,500;12..96,600;12..96,700;12..96,800&display=swap');
9	
10	  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
11	
12	  /* ── OKLCH tokens — warm dark base, single gold accent, no violet ── */
13	  :root {
14	    --gold:       oklch(72% 0.135 82);
15	    --gold-hi:    oklch(80% 0.13  82);
16	    --gold-dim:   oklch(56% 0.09  82);
17	    --gold-ghost: oklch(72% 0.135 82 / 0.12);
18	    --ink:        oklch(8%  0.013 75);
19	    --ink-2:      oklch(11% 0.013 75);
20	    --ink-3:      oklch(15% 0.013 75);
21	    --text:       oklch(93% 0.006 75);
22	    --text-mid:   oklch(58% 0.008 75);
23	    --text-low:   oklch(36% 0.007 75);
24	    --rule:       oklch(20% 0.010 75);
25	  }
26	
27	  html { scroll-behavior: smooth; }
28	  body {
29	    background-color: var(--ink);
30	    /* Ultra-faint dot grid — signals craft and precision at ~4% */
31	    background-image: radial-gradient(oklch(72% 0.135 82 / 0.055) 1px, transparent 1px);
32	    background-size: 28px 28px;
33	    color: var(--text);
34	    font-family: 'Bricolage Grotesque', system-ui, sans-serif;
35	    overflow-x: hidden;
36	    -webkit-font-smoothing: antialiased;
37	    position: relative;
38	  }
39	
40	  /* Page-wide cool atmospheric depth — violet as background element only,
41	     never on text or UI. Restores the Gold→Electric depth we dropped. */
42	  body::before {
43	    content: '';
44	    position: fixed; inset: 0; pointer-events: none; z-index: 0;
45	    background:
46	      radial-gradient(ellipse 70% 55% at 95% 5%,  oklch(56% 0.16 280 / 0.09) 0%, transparent 65%),
47	      radial-gradient(ellipse 55% 50% at 5%  95%, oklch(72% 0.135 82 / 0.07) 0%, transparent 65%),
48	      radial-gradient(ellipse 40% 40% at 50% 50%, oklch(56% 0.16 280 / 0.04) 0%, transparent 70%);
49	  }
50	
51	  /* ── KEYFRAMES ── */
52	  @keyframes letter-up {
53	    from { opacity: 0; transform: translateY(30px); }
54	    to   { opacity: 1; transform: translateY(0); }
55	  }
56	  @keyframes fade-up {
57	    from { opacity: 0; transform: translateY(22px); }
58	    to   { opacity: 1; transform: translateY(0); }
59	  }
60	  @keyframes fade-in {
61	    from { opacity: 0; } to { opacity: 1; }
62	  }
63	  @keyframes fade-down {
64	    from { opacity: 0; transform: translateY(-10px); }
65	    to   { opacity: 1; transform: translateY(0); }
66	  }
67	  @keyframes row-in {
68	    from { opacity: 0; transform: translateX(-18px); }
69	    to   { opacity: 1; transform: translateX(0); }
70	  }
71	  @keyframes scroll-pulse {
72	    0%,100% { opacity: 0.5; transform: scaleY(1); }
73	    50%     { opacity: 0.15; transform: scaleY(0.55); }
74	  }
75	  @keyframes marquee {
76	    from { transform: translateX(0); }
77	    to   { transform: translateX(-50%); }
78	  }
79	
80	  /* Scroll reveal classes */
81	  .reveal     { opacity: 0; transform: translateY(24px); will-change: transform,opacity; }
82	  .reveal-row { opacity: 0; transform: translateX(-16px); will-change: transform,opacity; }
83	  .reveal.visible     { animation: fade-up 0.65s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
84	  .reveal-row.visible { animation: row-in  0.55s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
85	  .s1 { animation-delay: 0ms   !important; }
86	  .s2 { animation-delay: 100ms !important; }
87	  .s3 { animation-delay: 200ms !important; }
88	
89	  /* Ensure all page content sits above the fixed atmospheric layer */
90	  nav, section, div, footer { position: relative; z-index: 1; }
91	
92	  /* ── NAV ── */
93	  nav {
94	    position: fixed; top: 0; left: 0; right: 0; z-index: 100;
95	    display: flex; align-items: center; justify-content: space-between;
96	    padding: 20px 72px;
97	    background: oklch(8% 0.013 75 / 0.85);
98	    backdrop-filter: blur(18px);
99	    border-bottom: 1px solid var(--rule);
100	    animation: fade-down 0.45s cubic-bezier(0.25, 0.46, 0.45, 0.94) 0.05s both;
101	  }
102	  .nav-logo {
103	    font-family: 'Cinzel', serif;
104	    font-size: 16px; font-weight: 900; letter-spacing: 0.18em;
105	    color: var(--gold);
106	  }
107	  .nav-links { display: flex; align-items: center; gap: 40px; list-style: none; }
108	  .nav-links a {
109	    font-size: 11px; font-weight: 500; letter-spacing: 0.09em; text-transform: uppercase;
110	    color: var(--text-mid); text-decoration: none;
111	    transition: color 180ms cubic-bezier(0.25, 0.46, 0.45, 0.94);
112	  }
113	  .nav-links a:hover { color: var(--text); }
114	
115	  /* Directional hover CTA button */
116	  .nav-cta {
117	    font-size: 11px; font-weight: 600; letter-spacing: 0.1em; text-transform: uppercase;
118	    padding: 9px 22px; border-radius: 3px;
119	    border: 1px solid oklch(72% 0.135 82 / 0.4);
120	    color: var(--gold); background: transparent; text-decoration: none;
121	    font-family: 'Bricolage Grotesque', sans-serif;
122	    position: relative; overflow: hidden;
123	    transition: color 200ms cubic-bezier(0.25, 0.46, 0.45, 0.94),
