125	                transform 150ms cubic-bezier(0.25, 0.46, 0.45, 0.94);
126	    display: inline-block;
127	  }
128	  .nav-cta::before {
129	    content: '';
130	    position: absolute; inset: 0;
131	    background: var(--gold);
132	    transform: translateX(-105%);
133	    transition: transform 250ms cubic-bezier(0.16, 1, 0.3, 1);
134	    z-index: -1;
135	  }
136	  .nav-cta:hover::before { transform: translateX(0); }
137	  .nav-cta:hover { color: var(--ink); border-color: var(--gold); }
138	  .nav-cta:active { transform: scale(0.97); transition-duration: 100ms; }
139	
140	  /* ── HERO — Left-aligned asymmetric (DESIGN_VARIANCE: 8) ── */
141	  .hero {
142	    min-height: 100dvh;
143	    display: grid;
144	    grid-template-columns: 1fr 0.7fr;
145	    align-items: center;
146	    padding: 130px 72px 90px;
147	    position: relative;
148	    overflow: hidden;
149	    gap: 40px;
150	  }
151	
