153	  .hero::before {
154	    content: '';
155	    position: absolute; inset: 0; pointer-events: none;
156	    background:
157	      radial-gradient(ellipse 60% 65% at 105% 10%, oklch(72% 0.135 82 / 0.14) 0%, transparent 70%),
158	      radial-gradient(ellipse 50% 55% at -5%  90%, oklch(72% 0.135 82 / 0.16) 0%, transparent 65%),
159	      radial-gradient(ellipse 75% 70% at 85%  40%, oklch(56% 0.16 280 / 0.10) 0%, transparent 60%),
160	      radial-gradient(ellipse 45% 45% at 30%  20%, oklch(56% 0.16 280 / 0.06) 0%, transparent 70%);
161	    animation: fade-in 1.4s cubic-bezier(0.25, 0.46, 0.45, 0.94) both;
162	  }
163	
164	  .hero-content { z-index: 1; }
165	
166	  /* Per-letter animated SOVEREIGN wordmark */
167	  .hero-wordmark {
168	    font-family: 'Cinzel', serif;
169	    font-size: clamp(52px, 6.5vw, 88px);
170	    font-weight: 900;
171	    letter-spacing: 0.06em;
172	    line-height: 1;
