178	    display: inline-block;
179	    animation: letter-up 0.6s cubic-bezier(0.16, 1, 0.3, 1) both;
180	    will-change: transform, opacity;
181	  }
182	
183	  .hero-tagline {
184	    font-size: clamp(14px, 1.4vw, 20px);
185	    font-weight: 600; letter-spacing: 0.04em;
186	    color: var(--text);
187	    margin-bottom: 20px;
188	    animation: fade-up 0.7s cubic-bezier(0.16, 1, 0.3, 1) 0.7s both;
189	  }
190	
191	  .hero-sub {
192	    font-size: clamp(14px, 1.1vw, 17px);
