661	<script>
662	  // ── Letter-stagger animation on SOVEREIGN wordmark ──
663	  const wordmark = document.getElementById('wordmark');
664	  const letters = 'SOVEREIGN'.split('');
665	  letters.forEach((char, i) => {
666	    const span = document.createElement('span');
667	    span.className = 'letter';
668	    span.textContent = char;
669	    span.style.animationDelay = `${0.3 + i * 0.045}s`;
670	    wordmark.appendChild(span);
671	  });
672	
673	  // ── Scroll reveal via IntersectionObserver ──
674	  // rootMargin -100px: fires 100px before viewport edge (Emil Kowalski rule)
675	  const observer = new IntersectionObserver(
676	    (entries) => entries.forEach((e) => {
677	      if (e.isIntersecting) { e.target.classList.add('visible'); observer.unobserve(e.target); }
678	    }),
679	    { rootMargin: '0px 0px -100px 0px', threshold: 0.05 }
680	  );
681	  document.querySelectorAll('.reveal, .reveal-row').forEach((el) => observer.observe(el));
682	
683	  // ── Spotlight effect on service rows ──
684	  // Updates CSS custom properties for the radial gradient position
685	  document.querySelectorAll('.service-row').forEach((row) => {
686	    row.addEventListener('mousemove', (e) => {
687	      const rect = row.getBoundingClientRect();
